## Code Example
```javascript
// Minimal walk in C-like pseudocode
uint32_t* walk(uint32_t* root, uint32_t va, int create){
  uint32_t l1 = (va >> 22) & 0x3FF;
  uint32_t l2 = (va >> 12) & 0x3FF;
  uint32_t offset = va & 0xFFF;
  uint32_t* pte1 = root + l1;
  if (!(*pte1 & 0x1)) { // not present
    if (!create) return NULL;
    uint32_t* newl2 = alloc_page();
    *pte1 = ((uint32_t)newl2) | 0x1; // mark present
  }
  uint32_t* l2tbl = (uint32_t*)(*pte1 & ~0xFFF);
  uint32_t* pte2 = l2tbl + l2;
  return pte2;
}
```

